/**
 * 影片筆記插件
 *
 * 在進度條上標記時間點並記錄筆記
 * - 工具列按鈕：點擊開啟筆記對話框
 * - 進度條標記：在對應時間點顯示小點
 * - Tooltip：hover 時顯示筆記內容
 */

import type { MpvPlugin, PluginInstance } from '../../core/types/plugin';
import type { MpvVideoElement } from '../../renderer/ui/MpvVideoElement';
import styles from './styles.css?inline';

/**
 * 筆記資料結構
 */
export interface Note {
    /** 筆記內容 */
    content: string;
    /** 影片時間點（秒） */
    videoTime: number;
    /** 建立時間 */
    createdAt: Date;
    /** 標記顏色（可選） */
    color?: string;
}

/**
 * 筆記插件配置
 */
export interface NotePluginOptions {
    /** 按鈕在控制列的順序，默認 75 */
    order?: number;
    /** 筆記最大字數限制，默認 500 */
    maxLength?: number;
}

/**
 * 筆記插件定義
 */
export const NotePlugin: MpvPlugin<NotePluginOptions> = {
    name: 'notes',
    version: '1.0.0',
    dependencies: ['progress'],
    styles,

    install(player, options = {}) {
        return new NoteManager(player, {
            order: options.order ?? 75,
            maxLength: options.maxLength ?? 500,
        });
    },
};

/**
 * 筆記管理器
 */
export class NoteManager implements PluginInstance {
    readonly name = 'notes';

    private player: MpvVideoElement;
    private options: Required<NotePluginOptions>;

    // 筆記資料
    private notes: Note[] = [];

    // DOM 元素
    private toggleBtn: HTMLElement | null = null;
    private dialogEl: HTMLElement | null = null;
    private markersContainer: HTMLElement | null = null;

    // 狀態
    private _enabled: boolean = true;
    private _dialogVisible: boolean = false;

    // 事件處理器（用於清理）
    private eventCleanups: Array<() => void> = [];

    constructor(player: MpvVideoElement, options: Required<NotePluginOptions>) {
        this.player = player;
        this.options = options;

        this.initialize();
    }

    private initialize(): void {
        const shadowRoot = this.player.shadowRoot;
        if (!shadowRoot) return;

        this.createToggleButton(shadowRoot);
        this.createDialog(shadowRoot);
        this.createMarkersContainer(shadowRoot);

        // 當 duration 可用時渲染標記
        this.player.addEventListener('durationchange', () => {
            this.renderMarkers();
        });
    }

    /**
     * 創建工具列按鈕
     */
    private createToggleButton(shadowRoot: ShadowRoot): void {
        const container = shadowRoot.querySelector('.vp-controls-right');
        if (!container) return;

        this.toggleBtn = document.createElement('button');
        this.toggleBtn.className = 'vp-btn vp-notes-btn';
        this.toggleBtn.title = '新增筆記 (N)';
        this.toggleBtn.dataset.order = String(this.options.order);
        this.toggleBtn.innerHTML = `
            <svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor">
                <path d="M19 3H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2zm0 16H5V5h14v14z"/>
                <path d="M7 7h10v2H7zM7 11h10v2H7zM7 15h7v2H7z"/>
            </svg>
        `;

        this.addEvent(this.toggleBtn, 'click', (e: Event) => {
            e.stopPropagation();
            this.showDialog();
        });

        this.insertByOrder(container, this.toggleBtn);
    }

    /**
     * 創建筆記輸入對話框
     */
    private createDialog(shadowRoot: ShadowRoot): void {
        this.dialogEl = document.createElement('div');
        this.dialogEl.className = 'mpv-notes-dialog hidden';
        this.dialogEl.innerHTML = `
            <div class="mpv-notes-dialog-content">
                <div class="mpv-notes-dialog-header">
                    <span class="mpv-notes-dialog-title">新增筆記</span>
                    <span class="mpv-notes-dialog-time"></span>
                </div>
                <textarea
                    class="mpv-notes-textarea"
                    placeholder="在此輸入筆記內容..."
                    maxlength="${this.options.maxLength}"
                ></textarea>
                <div class="mpv-notes-dialog-footer">
                    <span class="mpv-notes-char-count">0 / ${this.options.maxLength}</span>
                    <div class="mpv-notes-dialog-actions">
                        <button class="mpv-notes-btn-cancel">取消</button>
                        <button class="mpv-notes-btn-save">儲存</button>
                    </div>
                </div>
            </div>
        `;

        // 綁定事件
        const textarea = this.dialogEl.querySelector('.mpv-notes-textarea') as HTMLTextAreaElement;
        const charCount = this.dialogEl.querySelector('.mpv-notes-char-count') as HTMLElement;
        const cancelBtn = this.dialogEl.querySelector('.mpv-notes-btn-cancel') as HTMLButtonElement;
        const saveBtn = this.dialogEl.querySelector('.mpv-notes-btn-save') as HTMLButtonElement;

        this.addEvent(textarea, 'input', () => {
            charCount.textContent = `${textarea.value.length} / ${this.options.maxLength}`;
        });

        this.addEvent(cancelBtn, 'click', () => {
            this.hideDialog();
        });

        this.addEvent(saveBtn, 'click', () => {
            this.saveNote(textarea.value);
        });

        // 點擊背景關閉
        this.addEvent(this.dialogEl, 'click', (e: Event) => {
            if (e.target === this.dialogEl) {
                this.hideDialog();
            }
        });

        shadowRoot.appendChild(this.dialogEl);
    }

    /**
     * 創建進度條標記容器
     */
    private createMarkersContainer(shadowRoot: ShadowRoot): void {
        const progressBar = shadowRoot.querySelector('.mpv-progress-bar, .vp-progress-bar');
        if (!progressBar) return;

        this.markersContainer = document.createElement('div');
        this.markersContainer.className = 'mpv-notes-markers';
        progressBar.appendChild(this.markersContainer);
    }

    /**
     * 顯示對話框
     */
    showDialog(): void {
        if (!this.dialogEl) return;

        // 暫停播放
        const wasPlaying = !this.player.paused;
        if (wasPlaying) {
            this.player.pause();
        }

        // 更新時間顯示
        const timeEl = this.dialogEl.querySelector('.mpv-notes-dialog-time') as HTMLElement;
        if (timeEl) {
            timeEl.textContent = this.formatTime(this.player.currentTime);
        }

        // 清空輸入框
        const textarea = this.dialogEl.querySelector('.mpv-notes-textarea') as HTMLTextAreaElement;
        const charCount = this.dialogEl.querySelector('.mpv-notes-char-count') as HTMLElement;
        if (textarea) {
            textarea.value = '';
            textarea.focus();
        }
        if (charCount) {
            charCount.textContent = `0 / ${this.options.maxLength}`;
        }

        this.dialogEl.classList.remove('hidden');
        this._dialogVisible = true;
    }

    /**
     * 隱藏對話框
     */
    hideDialog(): void {
        if (!this.dialogEl) return;

        this.dialogEl.classList.add('hidden');
        this._dialogVisible = false;
    }

    /**
     * 儲存筆記
     */
    private saveNote(content: string): void {
        const trimmedContent = content.trim();
        if (!trimmedContent) {
            this.hideDialog();
            return;
        }

        const note: Note = {
            content: trimmedContent,
            videoTime: this.player.currentTime,
            createdAt: new Date(),
        };

        this.notes.push(note);
        this.renderMarkers();
        this.hideDialog();

        console.log('[NotePlugin] Note saved:', note);
    }

    /**
     * 渲染進度條標記
     */
    private renderMarkers(): void {
        if (!this.markersContainer) return;

        // 清空現有標記
        this.markersContainer.innerHTML = '';

        const duration = this.player.duration;
        if (!duration) return;

        // 為每個筆記創建標記
        for (let i = 0; i < this.notes.length; i++) {
            const note = this.notes[i];
            const marker = document.createElement('div');
            marker.className = 'mpv-notes-marker';
            marker.dataset.noteIndex = String(i);

            const percent = (note.videoTime / duration) * 100;
            marker.style.left = `${percent}%`;

            // 自訂顏色
            if (note.color) {
                marker.style.background = note.color;
            }

            // 在 marker 內建立 tooltip 文字
            const tooltip = document.createElement('div');
            tooltip.className = 'mpv-notes-marker-tooltip';
            tooltip.textContent = note.content;
            marker.appendChild(tooltip);

            // Hover 時禁用 thumbnail tooltip
            this.addEvent(marker, 'mouseenter', (e: MouseEvent) => {
                e.stopPropagation();
                (this.player as any).tooltipEnabled = false;
            });

            this.addEvent(marker, 'mouseleave', () => {
                (this.player as any).tooltipEnabled = true;
            });

            // 點擊跳轉
            this.addEvent(marker, 'click', (e: Event) => {
                e.stopPropagation();
                this.player.currentTime = note.videoTime;
            });

            this.markersContainer.appendChild(marker);
        }
    }

    // ===== 工具方法 =====

    private formatTime(seconds: number): string {
        if (!isFinite(seconds)) return '--:--';
        const mins = Math.floor(seconds / 60);
        const secs = Math.floor(seconds % 60);
        return `${mins}:${secs.toString().padStart(2, '0')}`;
    }

    private insertByOrder(container: Element, element: HTMLElement): void {
        const order = parseInt(element.dataset.order || '999', 10);
        const children = Array.from(container.children) as HTMLElement[];

        const insertBefore = children.find(child => {
            const childOrder = parseInt(child.dataset.order || '999', 10);
            return childOrder > order;
        });

        if (insertBefore) {
            container.insertBefore(element, insertBefore);
        } else {
            container.appendChild(element);
        }
    }

    private addEvent<K extends keyof HTMLElementEventMap>(
        target: HTMLElement | Document,
        event: K,
        handler: (e: HTMLElementEventMap[K]) => void
    ): void {
        target.addEventListener(event, handler as EventListener);
        this.eventCleanups.push(() => {
            target.removeEventListener(event, handler as EventListener);
        });
    }

    // ===== 公開 API =====

    /** 獲取所有筆記 */
    getNotes(): Note[] {
        return [...this.notes];
    }

    /** 新增筆記（程式化方式） */
    addNote(content: string, videoTime?: number): Note {
        const note: Note = {
            content,
            videoTime: videoTime ?? this.player.currentTime,
            createdAt: new Date(),
        };
        this.notes.push(note);
        this.renderMarkers();
        return note;
    }

    /** 刪除筆記 */
    removeNote(index: number): boolean {
        if (index < 0 || index >= this.notes.length) return false;
        this.notes.splice(index, 1);
        this.renderMarkers();
        return true;
    }

    /** 清空所有筆記 */
    clearNotes(): void {
        this.notes = [];
        this.renderMarkers();
    }

    /** 匯出筆記（JSON 格式） */
    exportNotes(): string {
        return JSON.stringify(this.notes, null, 2);
    }

    /** 匯入筆記（JSON 格式） */
    importNotes(json: string): boolean {
        try {
            const data = JSON.parse(json);
            if (!Array.isArray(data)) return false;

            this.notes = data.map(item => ({
                content: String(item.content || ''),
                videoTime: Number(item.videoTime) || 0,
                createdAt: new Date(item.createdAt || Date.now()),
                color: item.color,
            }));
            this.renderMarkers();
            return true;
        } catch {
            return false;
        }
    }

    enable(): void {
        this._enabled = true;
        this.toggleBtn?.classList.remove('disabled');
    }

    disable(): void {
        this._enabled = false;
        this.toggleBtn?.classList.add('disabled');
        this.hideDialog();
    }

    get enabled(): boolean {
        return this._enabled;
    }

    destroy(): void {
        // 清理事件監聽
        for (const cleanup of this.eventCleanups) {
            cleanup();
        }
        this.eventCleanups = [];

        // 移除 DOM
        this.toggleBtn?.remove();
        this.dialogEl?.remove();
        this.markersContainer?.remove();
    }
}

